use std::{fs,path::{Path,PathBuf},process::Command,io::Write};use serde_json::json;use sha2::{Sha256,Digest};
type R<T>=Result<T,Box<dyn std::error::Error>>;
fn h(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
fn paths(p:&Path,r:&Path,v:&mut Vec<PathBuf>)->R<()>{for e in fs::read_dir(p)?{let e=e?;if e.file_type()?.is_symlink(){return Err("Enlace no permitido".into())}if e.file_type()?.is_dir(){paths(&e.path(),r,v)?}else{v.push(e.path().strip_prefix(r)?.to_path_buf());}}Ok(())}
fn save(p:&Path,b:&[u8])->R<()>{let mut f=fs::OpenOptions::new().create_new(true).write(true).open(p)?;f.write_all(b)?;f.sync_all()?;Ok(())}
fn main()->R<()>{let a=std::env::args().collect::<Vec<_>>();let original=Path::new(&a[1]);let out=Path::new(&a[2]);let commit=&a[3];let remote=&a[4];let repo=a.get(5).ok_or("Repositorio requerido")?;if !matches!(repo.as_str(),"SV-motor"|"SV-lenguaje-de-computacion"|"SV-sala-de-maquinas"){return Err("Repositorio fuera de alcance".into())}fs::create_dir_all(out)?;let mut files=Vec::new();paths(original,original,&mut files)?;files.sort();let mut rows=Vec::new();
 for n in files{let rel=n.to_string_lossy().replace('\\',"/");let expected=fs::read(original.join(&n))?;let dst=out.join(&n);let actual=if dst.exists(){fs::read(&dst)?}else{let endpoint=format!("repos/juantoniolloretegea/{repo}/contents/{remote}/{rel}?ref={commit}");let r=Command::new("C:/Program Files/GitHub CLI/gh.exe").args(["api","-H","Accept: application/vnd.github.raw+json",&endpoint]).output()?;if !r.status.success(){return Err(format!("Recuperación {rel}: {}",String::from_utf8_lossy(&r.stderr)).into())}fs::create_dir_all(dst.parent().unwrap())?;save(&dst,&r.stdout)?;r.stdout};
 if actual!=expected{return Err(format!("Copia distinta: {rel}").into())}rows.push(json!({"archivo":rel,"bytes":actual.len(),"sha256":h(&actual),"igualdad_exacta":true}));println!("Cotejado: {rel}");
 }let report=json!({"conforme":true,"commit":commit,"repositorio":repo,"ruta_remota":remote,"archivos":rows,"metodo":"Recuperación individual por referencia Git inmutable y cotejo exacto de bytes y SHA-256 en Rust.","recepcion_independiente":"pendiente"});save(&out.parent().unwrap().join("COTEJO-DOCUMENTOS-GITHUB.json"),&serde_json::to_vec_pretty(&report)?)?;Ok(())}
